def find_nth_prime(n):
    primes = []
    num = 1
    while len(primes) < n:
        num += 1
        is_prime = True
        for p in primes:
            if p * p > num:
                break
            if num % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
    return primes[-1]

