def check_triple(x, y, z):
    try:
        # Calculate P = y^x * z^y * x^z
        # Handle potential issues with negative bases and exponents carefully,
        # but for integer results, we assume standard mathematical definitions.
        P = (y**x) * (z**y) * (x**z)
        if isinstance(P, int) and P > 0:
            # Check if P is prime
            if P == 1:
                return False
            i = 2
            while i * i <= P:
                if P % i == 0:
                    return False
                i += 1
            return True
        return False
    except OverflowError:
        return False
    except ZeroDivisionError:
        return False

